insert into public.content_drafts(id,kind,slug,document)values('948d5ff8-252f-58b9-aee2-b72b4b618348','settings','global','{"name":"RIVTON Group","whatsapp":"5493513437509","email":"rivtongroup@gmail.com","address":"Luis José de Tejeda 3883, local A, Córdoba Capital, Argentina.","hours":"Lunes a viernes de 8:30 a 18:00; sábados, domingos y feriados cerrado","instagram":"https://www.instagram.com/rivtongroup/","temporariesUrl":"https://www.tempohogar.com.ar/","footerText":"Propiedades con criterio, en Córdoba.","presentation":"Conectamos personas con oportunidades inmobiliarias, ofreciendo confianza, compromiso y soluciones a medida en cada operación.","history":"RIVTON Group nace de la fusión de dos empresas amigas, el 03/11/2025.","services":["Venta","Alquiler","Tasaciones","Administración de alquileres","Asesoramiento a inversores","Comercialización de desarrollos"],"values":["Confianza","Compromiso","Profesionalismo","Cercanía","Proyección","Excelencia"],"coverage":"Toda la provincia de Córdoba","whatsappTemplate":"Hola, quisiera consultar por la propiedad {title} (código {code}). {url}","filters":[{"key":"operacion","label":"Operación","visible":true,"order":0},{"key":"ubicacion","label":"Ubicación","visible":true,"order":1},{"key":"tipo","label":"Tipo de inmueble","visible":true,"order":2},{"key":"precioMax","label":"Precio máximo","visible":true,"order":3},{"key":"dormitorios","label":"Dormitorios","visible":true,"order":4},{"key":"banos","label":"Baños","visible":true,"order":5},{"key":"piscina","label":"Con piscina","visible":true,"order":6},{"key":"orden","label":"Ordenar","visible":true,"order":7},{"key":"moneda","label":"moneda","visible":false,"order":8},{"key":"superficieMin","label":"superficieMin","visible":false,"order":9},{"key":"caracteristicas","label":"caracteristicas","visible":false,"order":10}],"menu":[{"label":"Explorar propiedades","href":"/propiedades"},{"label":"Favoritos","href":"/favoritos"},{"label":"Publicá tu propiedad","href":"/publicar"},{"label":"Nosotros","href":"/nosotros"},{"label":"Contacto","href":"/contacto"},{"label":"Temporarios","href":"https://www.tempohogar.com.ar/"}],"theme":{"colors":{}}}'::jsonb)on conflict(id)do nothing;
insert into public.content_revisions(resource_id,revision,document,status)select id,revision,document,status from public.content_drafts where id='948d5ff8-252f-58b9-aee2-b72b4b618348' and revision=1 on conflict(resource_id,revision)do nothing;
