insert into public.content_drafts(id,kind,slug,document)values('2c99cb44-e8ce-5055-acef-cc1b761a4109','page','preguntas-frecuentes','{"title":"Preguntas frecuentes","slug":"preguntas-frecuentes","elements":[{"id":"faq-1","label":"Cómo consultar una propiedad","title":"Cómo consultar una propiedad","subtitle":"","body":"Usá el botón de consulta de la ficha o escribinos por WhatsApp al +54 9 351 3437509. Indicá el nombre o código de la propiedad para que podamos identificarla.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true},{"id":"faq-2","label":"Cómo coordinar una visita","title":"Cómo coordinar una visita","subtitle":"","body":"Contactá a RIVTON por WhatsApp. El equipo confirmará la disponibilidad del inmueble y acordará el día y horario. Abrir el enlace de contacto no confirma una visita.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true},{"id":"faq-3","label":"Cómo publicar una propiedad","title":"Cómo publicar una propiedad","subtitle":"","body":"Completá el formulario Publicá tu propiedad con la información del inmueble. El equipo te orientará sobre los próximos pasos y la documentación necesaria.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true},{"id":"faq-4","label":"Cómo solicitar una tasación","title":"Cómo solicitar una tasación","subtitle":"","body":"Escribinos con la ubicación y las características del inmueble. Los alcances del servicio y cualquier condición comercial se acuerdan directamente con el equipo.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true},{"id":"faq-5","label":"Cómo consultar por alquileres","title":"Cómo consultar por alquileres","subtitle":"","body":"Buscá la operación Alquiler y consultá por el inmueble que te interese. La disponibilidad y los requisitos se confirman para cada caso.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true},{"id":"faq-6","label":"Cómo consultar por una compra","title":"Cómo consultar por una compra","subtitle":"","body":"Elegí una propiedad y envianos tu consulta. Podés indicar la zona, el tipo de inmueble y tus necesidades para recibir orientación.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true},{"id":"faq-7","label":"Qué documentación se solicita","title":"Qué documentación se solicita","subtitle":"","body":"La documentación depende de la operación y de las circunstancias del inmueble y de las partes. Solicitá al equipo el detalle aplicable antes de avanzar.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true},{"id":"faq-8","label":"Cómo contactar a RIVTON","title":"Cómo contactar a RIVTON","subtitle":"","body":"Podés escribir a rivtongroup@gmail.com o por WhatsApp al +54 9 351 3437509. Atendemos de lunes a viernes de 8:30 a 18:00.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true}],"reviewApproved":false,"seo":{"title":"Preguntas frecuentes — RIVTON Group","description":"Preguntas frecuentes de RIVTON Group, inmobiliaria en Córdoba.","index":true,"manual":false}}'::jsonb)on conflict(id)do nothing;
