insert into public.content_drafts(id,kind,slug,document)values('c34a38fb-f9b6-5b89-a158-169b9b8ed662','page','privacidad','{"title":"Política de privacidad","slug":"privacidad","elements":[{"id":"legal","label":"Texto legal","title":"Política de privacidad","subtitle":"","body":"BORRADOR PARA REVISIÓN. Pendientes: identidad y domicilio legal del responsable, CUIT si corresponde, plazos de conservación, proveedores efectivos, transferencias internacionales, inscripción de bases cuando corresponda y procedimiento interno de derechos.\n\nRIVTON Group informa sobre el tratamiento de datos que se realice mediante este sitio. El canal de consulta es rivtongroup@gmail.com; la oficina comercial informada se encuentra en Luis José de Tejeda 3883, local A, Córdoba Capital, Argentina. La identificación jurídica del responsable debe confirmarse antes de publicar.\n\nLos formularios pueden solicitar nombre, teléfono, email, mensaje y datos del inmueble para responder consultas, coordinar conversaciones y evaluar solicitudes de comercialización. No se solicitan datos sensibles ni documentación personal en los campos generales. Los campos obligatorios deben identificarse; los opcionales pueden omitirse.\n\nEl almacenamiento de consultas permanece desactivado hasta aprobar la finalidad, la base jurídica y la información al titular. Cuando se habilite, el acceso estará limitado al personal autorizado. Deben establecerse plazos concretos de conservación y eliminación, incluyendo copias de seguridad. No se utilizarán consultas para publicidad distinta de la finalidad informada sin la autorización que corresponda.\n\nSi el visitante elige continuar por WhatsApp, se abrirá un servicio externo con un mensaje que podrá revisar antes de enviarlo. Esta acción se rige también por las condiciones y prácticas del proveedor elegido. Abrir el enlace no acredita recepción de un mensaje por RIVTON.\n\nLas personas titulares pueden solicitar información, acceso, rectificación, actualización o supresión de sus datos y presentar reclamos ante la Agencia de Acceso a la Información Pública. RIVTON deberá verificar la identidad de manera proporcionada y responder conforme a los plazos legales aplicables.\n\nLas medidas de seguridad reducen riesgos, sin garantizar inmunidad absoluta. Cualquier cambio relevante de finalidad o proveedores exige revisar este documento y los consentimientos. La fecha de entrada en vigencia se completará tras la aprobación.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true}],"reviewApproved":false,"seo":{"title":"Política de privacidad — RIVTON Group","description":"Política de privacidad de RIVTON Group, inmobiliaria en Córdoba.","index":true,"manual":false}}'::jsonb)on conflict(id)do nothing;
insert into public.content_revisions(resource_id,revision,document,status)select id,revision,document,status from public.content_drafts where id='c34a38fb-f9b6-5b89-a158-169b9b8ed662' and revision=1 on conflict(resource_id,revision)do nothing;
insert into public.content_drafts(id,kind,slug,document)values('f4e2acef-a5b1-5788-a620-e48ba904769e','page','cookies','{"title":"Política de cookies","slug":"cookies","elements":[{"id":"legal","label":"Texto legal","title":"Política de cookies","subtitle":"","body":"BORRADOR PARA REVISIÓN. Pendientes: inventario real de cookies, duraciones, proveedores, base jurídica y transferencias.\n\nEste sitio distingue tecnologías necesarias para iniciar sesión, proteger formularios y conservar preferencias, de tecnologías de analítica o publicidad. Estas últimas se mantienen bloqueadas hasta contar con la autorización o fundamento aplicable.\n\nEl visitante podrá aceptar o rechazar categorías no esenciales y modificar posteriormente su preferencia. El rechazo no debe impedir consultar el catálogo público. La elección se conservará en el dispositivo por un plazo que debe definirse y comunicarse.\n\nLos identificadores de medición no activan por sí solos una integración. Antes de habilitarla se verificará qué información se transmite, con qué finalidad y a qué destinatarios. No se incluirán mensajes de formularios, teléfonos ni emails en eventos o URLs de medición.\n\nLos favoritos se conservan localmente en el dispositivo. Los enlaces externos, incluidos WhatsApp y alojamientos temporarios, tienen políticas propias. El navegador permite borrar o restringir cookies, aunque algunas funciones necesarias pueden dejar de operar.\n\nLas consultas pueden dirigirse a rivtongroup@gmail.com. El inventario definitivo deberá reflejar las tecnologías realmente configuradas y su revisión deberá acompañar cada cambio relevante.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true}],"reviewApproved":false,"seo":{"title":"Política de cookies — RIVTON Group","description":"Política de cookies de RIVTON Group, inmobiliaria en Córdoba.","index":true,"manual":false}}'::jsonb)on conflict(id)do nothing;
insert into public.content_revisions(resource_id,revision,document,status)select id,revision,document,status from public.content_drafts where id='f4e2acef-a5b1-5788-a620-e48ba904769e' and revision=1 on conflict(resource_id,revision)do nothing;
insert into public.content_drafts(id,kind,slug,document)values('26748787-90c4-5c46-ac04-d3c4184593f9','page','terminos','{"title":"Términos y condiciones","slug":"terminos","elements":[{"id":"legal","label":"Texto legal","title":"Términos y condiciones","subtitle":"","body":"BORRADOR PARA REVISIÓN. Pendientes: razón social o responsable legal, CUIT, matrícula profesional, domicilio legal y condiciones comerciales aplicables.\n\nEl sitio de RIVTON Group ofrece información sobre inmuebles y canales de contacto en la provincia de Córdoba. La información no constituye por sí sola una reserva, aceptación contractual, garantía de disponibilidad ni asesoramiento jurídico individual.\n\nLos precios, superficies, características, fotografías y estados deberán verificarse con el equipo para cada operación. La moneda se identifica en cada publicación y no se convierte automáticamente. Si la ficha indica precio a consultar, el importe debe solicitarse al equipo.\n\nUna consulta por formulario o WhatsApp no perfecciona una compraventa, alquiler ni encargo de comercialización. Las visitas requieren confirmación expresa. Los honorarios, gastos, documentación y demás condiciones se informan y acuerdan en la instancia correspondiente; este documento no fija valores no confirmados.\n\nQuien solicita publicar un inmueble debe estar autorizado para aportar su información y materiales. El equipo podrá revisar datos y requerir documentación por canales adecuados antes de comercializarlo. No deben enviarse archivos ilícitos, datos sensibles innecesarios ni contenidos que infrinjan derechos de terceros.\n\nNo se autoriza interferir con el sitio, extraer datos personales, intentar accesos privados ni utilizar formularios para spam. Los enlaces a terceros se identifican como externos y no implican que RIVTON controle sus servicios.\n\nSe procurará mantener el sitio disponible y actualizado, sin garantizar ausencia absoluta de errores o interrupciones. La revisión jurídica deberá determinar las condiciones de responsabilidad y solución de controversias que correspondan sin limitar derechos obligatorios. Contacto: rivtongroup@gmail.com.","mobile":{},"desktop":{},"visible":true,"propertyIds":[],"categoryIds":[],"automatic":true}],"reviewApproved":false,"seo":{"title":"Términos y condiciones — RIVTON Group","description":"Términos y condiciones de RIVTON Group, inmobiliaria en Córdoba.","index":true,"manual":false}}'::jsonb)on conflict(id)do nothing;
